import sys,json,html
data = sys.stdin.read()
try:
    d = json.loads(data)
    for item in d.get('data',{}).get('items',[])[:10]:
        title = item.get('title','')
        url = item.get('url','')
        print(f'{title}\n  {url}\n')
except:
    print('parse error, raw:', data[:500])
" 2>/dev/null", "timeout": 10}

